    /// The grain tile: monochrome value noise (two octaves, contrast ×3), `px` square, deterministic, mid-grey mean.
    /// Draw it with `.overlay` at grainLight / grainDark, one tile pixel per device pixel.
    static let grainTile: CGImage = {
        let n = 256
        var seed: UInt64 = 0x9E3779B97F4A7C15
        func rnd() -> Double { seed = seed &* 6364136223846793005 &+ 1442695040888963407; return Double(seed >> 33) / Double(1 << 31) }
        func lattice(_ cells: Int) -> [Double] { (0..<(cells * cells)).map { _ in rnd() } }
        func octave(_ cells: Int, _ g: [Double], _ x: Int, _ y: Int) -> Double {
            let fx = Double(x) * Double(cells) / Double(n), fy = Double(y) * Double(cells) / Double(n)
            let x0 = Int(fx) % cells, y0 = Int(fy) % cells, x1 = (x0 + 1) % cells, y1 = (y0 + 1) % cells
            let tx = fx - floor(fx), ty = fy - floor(fy)
            let sx = tx * tx * (3 - 2 * tx), sy = ty * ty * (3 - 2 * ty)
            let a = g[y0 * cells + x0] + (g[y0 * cells + x1] - g[y0 * cells + x0]) * sx
            let b = g[y1 * cells + x0] + (g[y1 * cells + x1] - g[y1 * cells + x0]) * sx
            return a + (b - a) * sy
        }
        let c1 = 128, c2 = 256
        let g1 = lattice(c1), g2 = lattice(c2)
        var px = [UInt8](repeating: 0, count: n * n)
        for y in 0..<n { for x in 0..<n {
            let v = octave(c1, g1, x, y) * 0.6 + octave(c2, g2, x, y) * 0.4
            px[y * n + x] = UInt8(max(0, min(255, ((v - 0.5) * 3 + 0.5) * 255)))
        } }
        let data = CFDataCreate(nil, px, px.count)!
        return CGImage(width: n, height: n, bitsPerComponent: 8, bitsPerPixel: 8, bytesPerRow: n,
                       space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGBitmapInfo(rawValue: 0),
                       provider: CGDataProvider(data: data)!, decode: nil, shouldInterpolate: false, intent: .defaultIntent)!
    }()

    /// Tiles the grain over `r` with an overlay blend, one noise pixel per device pixel (`scale` = backing scale).
    static func drawGrain(in r: CGRect, ctx: CGContext, opacity: CGFloat, scale: CGFloat) {
