        ctx.saveGState()
        ctx.clip(to: r)
        ctx.setBlendMode(.overlay)
        ctx.setAlpha(opacity)
        ctx.scaleBy(x: 1 / scale, y: 1 / scale)
        let t = CGFloat(grainTile.width)
        ctx.draw(grainTile, in: CGRect(x: 0, y: 0, width: t, height: t), byTiling: true)
        ctx.restoreGState()
    }
